using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class AttendanceEvidenceTests
{
 class User(int employee=6,bool all=true):ICurrentUser{public string Email=>"evidence@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>all;public bool Can(string p)=>all;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static DeviceService Device(AppDbContext d){var u=new User();var c=new AppClock(TimeProvider.System);return new(d,c,new AuditService(d,u,c),u);}
 static AttendanceService Att(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a));}
 [Fact]public async Task DuplicatePunchesWithinBatchAndRetryAreIdempotent(){await using var d=await Db();var svc=Device(d);var e=await d.Set<Employee>().FindAsync(6);var at=new DateTime(2026,11,23,9,0,0);var punches=new[]{new DeviceService.PunchIn(e!.Code,at),new DeviceService.PunchIn(" "+e.Code.ToLowerInvariant()+" ",at)};Assert.Equal(1,await svc.IngestAsync(punches));Assert.Equal(0,await svc.IngestAsync(punches));Assert.Equal(1,await d.Set<DevicePunch>().CountAsync());Assert.Single(await d.Set<AttendanceEvidence>().ToListAsync());}
 [Fact]public async Task DatabaseRejectsDuplicateIdempotencyKey(){await using var d=await Db();d.Add(new DevicePunch{IdempotencyKey="duplicate"});await d.SaveAsync();d.Add(new DevicePunch{IdempotencyKey="duplicate"});await Assert.ThrowsAsync<DbUpdateException>(()=>d.SaveAsync());}
 [Fact]public async Task RawPunchCannotBeChangedOrDeleted(){await using var d=await Db();d.Add(new DevicePunch{DeviceUserId="original"});await d.SaveAsync();var p=await d.Set<DevicePunch>().SingleAsync();p.DeviceUserId="tamper";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();p=await d.Set<DevicePunch>().SingleAsync();d.Remove(p);await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task AttendanceEvidenceCannotBeChangedOrDeleted(){await using var d=await Db();d.Add(new AttendanceEvidence{Reason="original"});await d.SaveAsync();var p=await d.Set<AttendanceEvidence>().SingleAsync();p.Reason="tamper";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();p=await d.Set<AttendanceEvidence>().SingleAsync();d.Remove(p);await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task InvalidLaterPunchRollsBackEarlierInsert(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>Device(d).IngestAsync([new("PH-006",new(2026,11,23,9,0,0)),new("",new(2026,11,23,9,0,0))]));Assert.False(await d.Set<DevicePunch>().AnyAsync());}
 [Fact]public async Task DeviceProjectionKeepsRawEvidenceAndDoesNotDuplicateHistory(){await using var d=await Db();var svc=Device(d);var e=await d.Set<Employee>().FindAsync(6);var day=new DateTime(2026,11,23);var rec=await d.Set<AttendanceRecord>().FirstAsync(x=>x.EmployeeId==6&&x.Date==day);rec.Source=AttendanceSource.Fingerprint;await d.SaveAsync();await svc.IngestAsync([new(e!.Code,day.AddHours(8)),new(e.Code,day.AddHours(17))]);var old=(await d.Set<AttendanceEvidence>().SingleAsync()).AfterIn;await svc.IngestAsync([new(e.Code,day.AddHours(7))]);Assert.Equal(3,await d.Set<DevicePunch>().CountAsync());Assert.Equal(old,(await d.Set<AttendanceEvidence>().OrderBy(x=>x.Id).FirstAsync()).AfterIn);Assert.Equal(2,await d.Set<AttendanceEvidence>().CountAsync());}
 [Fact]public async Task EvidenceReadRespectsEmployeeScope(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>Att(d,new User(6,false)).EvidenceAsync(1,2026,11));}
 [Fact]public async Task ManualEntryAndExcuseHaveEvidence(){await using var d=await Db();var svc=Att(d);var day=new DateTime(2026,11,1);var r=await d.Set<AttendanceRecord>().FirstOrDefaultAsync(x=>x.EmployeeId==6&&x.Date==day);if(r!=null){d.Remove(r);await d.SaveAsync();}await svc.AddManualAsync(6,day,day.AddHours(9),day.AddHours(17),AttendanceSource.Manual);Assert.Equal("ManualEntry",(await d.Set<AttendanceEvidence>().SingleAsync()).Event);var absent=day.AddDays(-1);await svc.ExcuseAbsenceAsync(6,absent,"Fictional excused absence");Assert.Equal(2,await d.Set<AttendanceEvidence>().CountAsync());}
 [Fact]public async Task NestedBusinessTransactionRollsBackAllEvidence(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await Device(d).IngestAsync([new("PH-006",new(2026,11,23,9,0,0))]);throw new DomainException("test");}));Assert.False(await d.Set<DevicePunch>().AnyAsync());Assert.False(await d.Set<AttendanceEvidence>().AnyAsync());}

 [Fact]public async Task ApprovedCorrectionPreservesBeforeAndAfterEvidence(){await using var d=await Db();var u=new User(1);var c=new AppClock(TimeProvider.System);var audit=new AuditService(d,u,c);var day=new DateTime(2026,11,23);var rec=await d.Set<AttendanceRecord>().FirstAsync(x=>x.EmployeeId==6&&x.Date==day);var oldIn=rec.CheckIn;var oldOut=rec.CheckOut;var request=new AttendanceCorrection{EmployeeId=6,Date=day,OldCheckIn=oldIn,OldCheckOut=oldOut,NewCheckIn=day.AddHours(8),NewCheckOut=day.AddHours(16),Reason="Approved evidence test",Route="HRManager"};d.Add(request);await d.SaveAsync();var n=new NotificationService(d,u,c);var svc=new ApprovalService(d,new AccessScope(d,u),u,audit,n,c,new WorkflowService(d,u,audit),new DelegationService(d,u,audit,c));await svc.ApproveAsync("Correction",request.Id,"checked");var ev=await d.Set<AttendanceEvidence>().SingleAsync();Assert.Equal(oldIn,ev.BeforeIn);Assert.Equal(oldOut,ev.BeforeOut);Assert.Equal(day.AddHours(8),ev.AfterIn);Assert.Equal(request.Id,ev.CorrectionId);Assert.Equal("Approved evidence test",ev.Reason);}
 [Fact]public async Task FailedFinalLeaveApprovalRollsBackApprovalAndLedger(){await using var d=await Db();var u=new User(1);var c=new AppClock(TimeProvider.System);var audit=new AuditService(d,u,c);var n=new NotificationService(d,u,c);var type=await d.Set<LeaveType>().FirstAsync(x=>x.DeductsBalance);var balance=await d.Set<LeaveBalance>().FirstAsync(x=>x.EmployeeId==6&&x.LeaveTypeId==type.Id);balance.Used=balance.Entitled+balance.CarriedOver;var request=new LeaveRequest{EmployeeId=6,LeaveTypeId=type.Id,StartDate=new(2026,12,1),EndDate=new(2026,12,1),Days=1,Route="HRManager"};d.Add(request);await d.SaveAsync();var id=request.Id;var svc=new ApprovalService(d,new AccessScope(d,u),u,audit,n,c,new WorkflowService(d,u,audit),new DelegationService(d,u,audit,c));await Assert.ThrowsAsync<DomainException>(()=>svc.ApproveAsync("Leave",id,null));var saved=await d.Set<LeaveRequest>().FindAsync(id);Assert.Equal(RequestStatus.Pending,saved!.Status);Assert.Equal(0,saved.StageIndex);Assert.False(await d.Set<LeaveTransaction>().AnyAsync(x=>x.RequestId==id));Assert.False(await d.Set<ApprovalAction>().AnyAsync(x=>x.Kind=="Leave"&&x.RequestId==id));}
}
